#!/usr/bin/env node
// Holds every `([validated by: <test name>](path#Lnn))` citation to the test it names.
//
// Usage:
//   node scripts/check-spec-anchor-names.mjs           # report, exit 1 on any finding
//   node scripts/check-spec-anchor-names.mjs --fix     # repoint each line from the name it carries
//
// A line number is the wrong thing to cite: inserting an import above a suite moves every test below
// it, and the citation silently lands on a different, still-valid declaration. The name is what the
// author meant, so the name is what the citation records and the line becomes a derived pointer this
// script repairs. The `#Lnn` stays because the lint rule and the coverage job both index by it, and a
// citation without one marks the whole file covered rather than one test.
import {readFileSync, writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import process from 'node:process';
import {dirname, join, normalize} from 'node:path';
import {root} from './lib/repo-root.mjs';

const CITATION = /\[validated by(?<label>: [^\]]*)?\]\((?<path>(?:\.\.\/)+[\w./-]+?)#L(?<line>\d+)\)/g;
// Any other href shape is refused rather than ignored: the coverage job resolves `./../x` and `/x`
// to the same file and counts them, while this gate and the drift check would never have read them.
const ANY_HREF = /\[validated by(?:: [^\]]*)?\]\((?<path>[^)#\s]+)#L\d+\)/g;
// `xit`, `xdescribe` and `.skip` declare a test that never runs, which validates nothing.
const DECLARATION = /^\s*(?:f?it|f?describe|test)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const SKIPPED = /^\s*(?:x(?:it|describe|test)|(?:it|describe|test)\.skip)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$/;

const cache = new Map();
const args = process.argv.slice(2);
const fix = args.includes('--fix');
const named = args.filter(arg => !arg.startsWith('--'));
const findings = [];
let checked = 0;
let repaired = 0;

for (const spec of named.length > 0 ? named : specs()) {
  const source = readFileSync(join(root, spec), 'utf8');
  const specDir = dirname(spec);
  let changed = false;

  for (const match of source.matchAll(ANY_HREF)) {
    if (!match.groups.path.startsWith('../')) {
      findings.push(`${spec}: href "${match.groups.path}" must be relative and start with ../`);
    }
  }

  const rewritten = source.replace(CITATION, (whole, label, path, line, ...rest) => {
    const groups = rest[rest.length - 1];
    const target = normalize(join(specDir, groups.path));
    if (!TEST_FILE.test(target)) return whole;

    checked += 1;
    const declarations = declarationsIn(target);
    if (declarations === null) {
      findings.push(`${spec}: ${groups.path} does not exist`);
      return whole;
    }

    const named = groups.label ? groups.label.slice(2) : null;
    const atLine = declarations.find(declaration => declaration.line === Number(groups.line));

    const skipped = declarations.find(d => d.skipped && (d.name === named || d.line === Number(groups.line)));
    if (skipped) {
      findings.push(`${spec}: cites "${skipped.name}" at ${groups.path}#L${skipped.line}, which is skipped and validates nothing`);
      return whole;
    }

    if (named === null) {
      if (!atLine) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} is not a declaration, so no name can be read from it`);
        return whole;
      }
      if (nameIsAmbiguous(declarations, atLine.name)) {
        findings.push(ambiguity(spec, groups.path, atLine.name, declarations));
        return whole;
      }
      if (!fix) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} carries no test name`);
        return whole;
      }
      return rewrite(atLine.name, groups.path, atLine.line);
    }

    // Checked before the line is consulted: a name that identifies two declarations is not an
    // identifier, and while the line happens to agree nothing would ever say so.
    if (nameIsAmbiguous(declarations, named)) {
      findings.push(ambiguity(spec, groups.path, named, declarations));
      return whole;
    }

    if (atLine && atLine.name === named) return whole;

    const [match] = declarations.filter(declaration => declaration.name === named);
    if (!match) {
      findings.push(`${spec}: names "${named}", which no declaration in ${groups.path} has`);
      return whole;
    }
    if (!fix) {
      findings.push(`${spec}: names "${named}" but points at #L${groups.line}; it is at #L${match.line}`);
      return whole;
    }
    return rewrite(named, groups.path, match.line);

    function rewrite(name, path, line) {
      // A name carrying a bracket would close the markdown label early: the citation stops being a
      // link, stops matching CITATION, and disappears from this gate and from the coverage job.
      if (/[[\]]/.test(name)) {
        findings.push(`${spec}: "${name}" carries a bracket and cannot be written into a markdown label`);
        return whole;
      }
      repaired += 1;
      changed = true;
      return citation(name, path, line);
    }
  });

  if (changed) writeFileSync(join(root, spec), rewritten);
}

for (const finding of findings) process.stderr.write(`check-spec-anchor-names: ${finding}\n`);

if (findings.length > 0) {
  process.stderr.write(`\ncheck-spec-anchor-names: ${findings.length} finding(s).\n`);
  process.stderr.write('Run `npm run spec:names -- --fix` to repoint a citation from the name it carries.\n');
  process.exit(1);
}

const verb = fix ? `repointed ${repaired},` : '';
process.stdout.write(`check-spec-anchor-names: ${verb} ${checked} citation(s) name the test they point at\n`);

function nameIsAmbiguous(declarations, name) {
  return declarations.filter(declaration => declaration.name === name && !declaration.skipped).length > 1;
}

function ambiguity(spec, path, name, declarations) {
  const lines = declarations.filter(declaration => declaration.name === name).map(d => `#L${d.line}`);
  return `${spec}: "${name}" names ${lines.length} declarations in ${path} (${lines.join(', ')}) — rename one`;
}

function citation(name, path, line) {
  return `[validated by: ${name}](${path}#L${line})`;
}

function declarationsIn(path) {
  if (cache.has(path)) return cache.get(path);

  let lines;
  try {
    lines = readFileSync(join(root, path), 'utf8').split('\n');
  } catch {
    cache.set(path, null);
    return null;
  }
  const found = lines.flatMap((text, index) => {
    const match = DECLARATION.exec(text);
    if (match) return [{line: index + 1, name: match[2], skipped: false}];
    const skipped = SKIPPED.exec(text);
    return skipped ? [{line: index + 1, name: skipped[2], skipped: true}] : [];
  });

  cache.set(path, found);
  return found;
}

function specs() {
  const out = execFileSync('git', ['ls-files', 'specs/**/*.md', 'adrs/*.md'], {cwd: root, encoding: 'utf8'});
  return out.trim().split('\n').filter(Boolean);
}

import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator, delegatingTo, stopTrackedEngines} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.

interface Frame {
  type: string;
  sessionId?: string;
  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
  code?: string;
  message?: string;
}

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];
const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];

beforeEach(() => {
  logLines.length = 0;
  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    void logLines.push({level, category, message, fields});
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
});

afterEach(async () => {
  await stopTrackedEngines(clients, servers);
  setLogger();
});

const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: userId}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  let connected: Frame = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      if (frame.type !== 'connected') {
        frames.push(frame);
        return;
      }
      connected = frame;
      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    });
  });
  return {connected, frames};
};

describe('listing conversations over the WebSocket protocol', () => {
  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    const inner = new InMemorySessionStore();
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: (userId, options) => {
        seen.push({userId, options});
        return summaries;
      },
    };
    const url = await startEngine(store, 'u1');
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect({seen, frames}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      frames: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
    const inner = new InMemorySessionStore();
    const withoutList = await startEngine(delegatingTo(inner));
    const failingList = await startEngine({
      ...delegatingTo(inner),
      listFor: () => Promise.reject(new Error('database offline')),
    });

    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});

    expect({
      unimplemented: unimplemented.frames,
      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR'}],
      logged: [
        {
          level: 'error',
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
        },
      ],
    });
  });

  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
    const inner = new InMemorySessionStore();
    let calls = 0;
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: () => {
        calls += 1;
        return [];
      },
    };
    const url = await startEngine(store);
    const badFrames = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    const codes: Array<string | undefined> = [];
    for (const bad of badFrames) {
      const {frames} = await askAfterConnect(url, bad);
      codes.push(frames[0]?.code);
    }
    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});

    expect({codes, accepted, calls}).toEqual({
      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
      accepted: [{type: 'session_list', sessions: []}],
      calls: 1,
    });
  });
});
import {WebSocket} from 'ws';
import type {SessionEntry} from '../../types/session.js';
import type {ChatSession} from '../../types/session.js';
import {ErrorCodes} from '../../types/messages.js';
import type {ConversationSummary, ListConversationsMessage, OutgoingMessage} from '../../types/messages.js';
import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
import {validateMessage} from './validation.js';
import type {ValidationResult} from './validation.js';
import {PerSessionLock} from '../../shared/perSessionLock.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
import type {SessionHistoryOptions} from './sessionResume.js';
import {StoreCannotList} from '../../types/sessionStore.js';
import {AIError} from '../../types/ai.js';
import type {MessageChunk} from '../../types/ai.js';
import {
  createUserEntry,
  createAssistantEntry,
  createThinkingEntry,
  createToolEntry,
} from '../../orchestration/entryFactories.js';
import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
import {log} from '../../shared/logger.js';

export interface MessageHandlerOptions {
  history?: SessionHistoryOptions;
}

interface StreamState {
  thinkingIndex: number | null;
  assistantIndex: number | null;
  suppressOutput: boolean;
  sentAssistantIndices: number[];
}

type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
export function createMessageHandler(
  orchestrator: ChatOrchestrator,
  sessionStore?: SessionStore,
  options: MessageHandlerOptions = {}
) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () =>
        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore, options)
      );
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore, options));
  };
}

// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
async function answerInTurn(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined,
  sessionStore: SessionStore | undefined,
  options: MessageHandlerOptions
): Promise<void> {
  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
    return;
  }
  const startedAt = Date.now();
  try {
    await wsErrorHandler(ws, () =>
      answerUserMessage(ws, session, orchestrator, validation, signal, sessionStore, options)
    );
  } finally {
    endTurn(ws, session, signal, startedAt);
  }
}

// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
  if (signal?.aborted) {
    log.info('message', 'turn abandoned: its socket closed', {
      sessionId: session.sessionId,
      elapsedMs: Date.now() - startedAt,
    });
    return;
  }
  sendStreamEnd(ws);
}

async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined,
  sessionStore: SessionStore | undefined,
  options: MessageHandlerOptions
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  await answerFrame(ws, session, validation, sessionStore, options);
}

async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore: SessionStore | undefined,
  options: MessageHandlerOptions
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_conversations') await answerConversationList(ws, session, sessionStore, options, message);
  if (message.type === 'list_sessions') await answerLegacySessionList(ws, session, sessionStore, message);
}

async function answerLegacySessionList(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: {type: 'list_sessions'; limit?: number; before?: {updatedAt: string; sessionId: string}}
): Promise<void> {
  try {
    const summaries = sessionStore?.listFor
      ? await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before})
      : [];
    sendJson(ws, {
      type: 'session_list',
      sessions: summaries.map(toConversationSummary),
    } as unknown as OutgoingMessage);
  } catch (error) {
    log.error('ws', 'conversation list failed', {
      userId: session.userId,
      error: error instanceof Error ? error.message : String(error),
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

async function answerConversationList(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  options: MessageHandlerOptions,
  message: ListConversationsMessage
): Promise<void> {
  if (!options.history?.enabled || !sessionStore?.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not available');
    return;
  }

  try {
    const userId = (ws as WebSocket & {userId?: string | number}).userId ?? session.userId;
    const summaries = await sessionStore.listFor(userId, {limit: message.limit, before: message.before});
    sendJson(ws, {
      type: 'conversation_list',
      conversations: summaries.map(toConversationSummary),
    });
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not available');
      return;
    }
    log.error('ws', 'conversation list failed', {
      sessionId: session.sessionId,
      error: error instanceof Error ? error.name : typeof error,
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

function toConversationSummary(summary: SessionSummary): ConversationSummary {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
function isUserMessageFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
}

async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
  try {
    await action();
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    const code = error instanceof AIError ? error.code : 'UNKNOWN';
    log.error('message', 'handling error', {error: message, code});
    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
      return;
    }
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
  }
}

async function handleUserMessage(
  ws: WebSocket,
  session: ChatSession,
import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage | LegacyListSessionsMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

interface LegacyListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: {updatedAt: string; sessionId: string};
}

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = messageValidators[message.type];
  return validator ? validator(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

const messageValidators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  ['user_message']: validateUserMessage,
  ping: validatePingMessage,
  ['list_conversations']: validateListConversationsMessage,
  ['list_sessions']: validateLegacyListSessionsMessage,
};

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if (!isValidLimit(limit)) {
    return {valid: false, error: 'list_conversations limit must be an integer from 1 to 200'};
  }

  if (message.before === undefined) {
    return {valid: true, data: {type: 'list_conversations', limit: typeof limit === 'number' ? limit : undefined}};
  }

  if (typeof message.before !== 'object' || message.before === null) {
    return {valid: false, error: 'list_conversations before must be a cursor object'};
  }

  const before = message.before as Record<string, unknown>;
  if (typeof before.updatedAt !== 'string' || !Number.isFinite(Date.parse(before.updatedAt))) {
    return {valid: false, error: 'list_conversations before.updatedAt must be a valid date string'};
